    -o-transition: all 0.3s ease;
    transition: all 0.3s ease;
    z-index: 0;
}

.hvr_img_box_container:before {
    background-color: #ffffff;
    bottom: 0;
    content: "";
    left: 0;
    position: absolute;
    right: 0;
    top: 0;
    -webkit-transition: all 0.3s ease;
