
@media (min-width: 991.98px){
    .side-fixed {
        position: fixed;
        left: 5vh;
        bottom: 10%;
        z-index: 1000;
    }
    .side-fixed .open {
        display: flex;
        flex-direction: column-reverse;
    }

    .side-fixed .open>.fa-commenting {
        background: var(--main-color);
        color: #fff;
        height: 43px;
        width: 42px;
        border: 0;
        border-radius: 25px;
        font-size: 1.5rem;
        padding: .3rem;
        display: flex;
        justify-content: center;
        align-items: center;
        cursor: pointer;
        z-index: 3;
        border: 1px solid rgba(255,255,255,.2);
    }
    .side-fixed .open ul {
        list-style: none;
        padding: 0;
        position: relative;
        visibility: hidden;
        display: block;
    }
    .side-fixed .open ul li {
        top: 0;
        position: absolute;
        padding: .3rem 0;
        width: auto;
        white-space: nowrap;
    }
    .side-fixed .open ul li button {
        padding: 0;
        border: 0;
        background: 0 0;
    }

    .side-fixed .open ul li a, .side-fixed .open ul li button {
        display: inline-flex;
        align-items: center;
        color: #fff;
    }

    .side-fixed .open ul li a i, .side-fixed .open ul li button i {
        background: var(--main-color);
        color: #fff;
        width: 36px;
        height: 37px;
        border-radius: 22px;
        font-size: 1.4rem;
        padding: .3rem;
        display: flex;
        justify-content: center;
        align-items: center;
        border: 1px solid rgba(255,255,255,.2);
    }

    .side-fixed .open ul li a .side-item, .side-fixed .open ul li button .side-item {
        display: inline-flex;
        align-items: center;
        background: #37404d;
        border-radius: 22px;
        padding: .2rem .5rem;
        font-size: 12px;
        height: 25px;
    }
    .side-fixed .open:hover ul {
        visibility: visible;
    }
    .side-fixed .open:hover ul {
        visibility: visible;
    }
    .side-fixed .open:hover ul li{
        transition: all .3s  ease-in-out;

    }
    .side-fixed .open:hover ul li:nth-child(1) {
        top: -45px;
    }
    .side-fixed .open:hover ul li:nth-child(2) {
        top: -90px;
    }
    .side-fixed .open:hover ul li:nth-child(3) {
        top: -135px;
    }
    .side-fixed .open:hover ul li:nth-child(4) {
        top: -180px;
    }

}
