  border: 0px;
  display: inline-block;
  margin: 0;
  padding: 0;
  text-align: left;
  /* float: left;*/
}

.ace-responsive-menu li a {
  color: #c0c0c0;
}

.ace-responsive-menu > li > a.active span {
  color: #ffffff;
