  padding-right: 10px;
}

.ace-responsive-menu li.menu-active > a {
  /*background: #272727 !important;*/
  color: #fff;
}

.ace-responsive-menu li .menu-active {
  position: relative;
}

.ace-responsive-menu > li > a > .arrow:before {
  margin-left: 8px;
  display: inline;
  font-size: 16px;
  font-family: FontAwesome;
  height: auto;
  content: "\f107";
  font-weight: 300;
  text-shadow: none;
  width: 10px;
