
#header{
    .site-header {
    background-color: #fff;
    .navbar {
        height: 120px;
        .toggler {
            background: 0 0;
            border: 0;
            -webkit-appearance: none;
            border-radius: 50%;
            cursor: pointer;
            .nav-icon {
                height: 4px;
                background-color: #37404d;
                margin: 6px 0;
                width: 32px;
                border-radius: 20%;
            }
        }
    }
    .navbar-collapse {
        display: flex;
        flex-wrap: wrap;
        height: 100px;
        align-self: flex-end;
        .close-nav {
            position: absolute;
            top: 20px;
            right: 15px;
            color: #37404d;
            cursor: pointer;
            z-index: 2;
        }
        .fa-times-circle {
            font-size: 1.5rem;
        }

        .nav-search {
            width: 230px;
            i {
                position: absolute;
                top: 50%;
                left: 5%;
                transform: translate(0,-50%);
                color: #000;
            }
            .form-control {
                width: 100%;
                height: 100%;
                font-size: .9rem;
                border: 0;
            }

        }
        .nav-call {
            padding: 0 7px;
            overflow: hidden;
            font-size: 16px;
            margin-left: auto;
            .call-item{
                padding: 8px 8px;
                i {
                    display: block;
                    position: relative;
                    margin-bottom: 16px;
                    transition: all .3s ease-in-out;
                    &:last-of-type {
                        color: var(--main-color);
                    }
                }

            }
            a{
                color: #37404d;
                padding: 8px 8px;
            }
            .fa-phone-volume {
                transform: rotate(-45deg);
            }
            a span {
                font-size: .9rem!important;
            }
        }
        .nav-social {
            padding: 0 5px;
            overflow: hidden;
            font-size: 16px;
            a {
                padding: 10px;
                color: #37404d;
                i {
                    display: block;
                    position: relative;
                    margin-bottom: 16px;
                    &:hover {
                        color: var(--main-color);
                        cursor: pointer;
                        -webkit-transition: background-color 2s ease-out;
                        -moz-transition: background-color 2s ease-out;
                        -o-transition: background-color 2s ease-out;
                        transition: background-color 2s ease-out;
                    }
                }
            }

        }
        .navbar-nav {
            align-self: flex-end;
            justify-content: space-around;
            .nav-item {
                margin: 0!important;
                padding: .7rem 0;
                display: flex;
                align-items: center;
                .nav-link {
                    font-size: .9rem;
                    color: #5f6670;
                    padding: 0;
                }
            }
        }
    }


}

}
.language {
    width: 50px;
    .btn {
        width: 100%;
        justify-content: center;
        align-items: center;
        height: 100%;
        padding: 0;
        &:after{
            display:none;

        }

    }
    .dropdown-menu {
        left: 50%;
        transform: translate(-50%);
        padding: 0;
        border: 0;
        border-radius: 4px;
        box-shadow: 0 3px 15px rgba(0,0,0,.15);

    }
    .dropdown-menu {
        min-width: auto;
        padding: .1rem;
        margin: 0;
        border-radius: 4px;
        border: 1px solid #eee;
        margin-top: .7rem;
        .lang-label {
            background: #c5c5c5;
            padding: 1px 10px;
            text-align: center;
            font-size: 14px;
            border-top-right-radius: 2px;
            border-top-left-radius: 2px;
        }
        .dropdown-item {
            display: flex;
            align-items: center;
            justify-content: flex-start;
            font-size: 14px;
            padding: 8px 10px;
            .lang-code {
                width: 30px;
                height: 30px;
                display: flex;
                justify-content: center;
                align-items: center;
                font-size: 13px;
                border-radius: 50%;
                background: var(--main-color);
                color: #fff;
            }
        }


    }
}

.currency {
